import os, glob, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    sessions_path = os.path.join(d, '..', '..')
    # Look for session file
    for root, dirs, files in os.walk(d):
        for f in files:
            if f.endswith('.jsonl'):
                path = os.path.join(root, f)
                try:
                    with open(path) as fh:
                        content = fh.read()
                        # Extract the demo pairs
                        demo_pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\nDemo pair|\nTest input|\Z)'
                        matches = list(re.finditer(demo_pattern, content, flags=re.DOTALL))
                        grids = {}
                        for m in matches:
                            key, h, w = m.group(1), int(m.group(2)), int(m.group(3))
                            grid_rows_str = m.group(4).strip()
                            if key.startswith('Demo pair'):
                                demo_num = int(key.split()[2])
                                task_id = grids.get('_taskid', key)
                            else:
                                task_id = 'test'
                            rows = [row.split() for row in grid_rows_str.split('\n')[:h]]
                            grids[(task_id, key)] = [[int(x) for x in row] for row in rows]
                        return grids
                except:
                    continue
    return {}

G = load_grids()
print("Loaded grids:", sorted(G.keys()))

