import json

def transform(grid):
    n = len(grid)

    def pat_A(grid, n):
        return [[grid[i][n-1-j] for j in range(n)] for i in range(n)]

    def pat_B(grid, n):
        result = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                result[j][n-1-i] = grid[i][j]
        return result

    def pat_C(grid, n):
        result = [[grid[n-1-i][n-1-j] for j in range(n)] for i in range(n)]
        return result

    def pat_D(grid, n):
        return [row[:] for row in grid]

    output = [[0]*(n*n) for _ in range(n*n)]

    for bi in range(n):
        for bj in range(n):
            if (bi, bj) == (1, 1):
                subgrid = pat_D(grid, n)
            elif (bi, bj) in [(1, 0), (1, 2)]:
                subgrid = pat_A(grid, n)
            elif (bi, bj) == (0, 1) or (bi, bj) == (2, 1):
                subgrid = pat_B(grid, n)
            else:
                subgrid = pat_C(grid, n)

            for i in range(n):
                for j in range(n):
                    output[bi*n + i][bj*n + j] = subgrid[i][j]

    return output

